import{_ as i,l as o,o as e,c as l,v as t,p as n,x as r,d as p,i as d,S as _}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Saga","description":"","frontmatter":{"title":"Saga","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/saga-pattern.md","filePath":"cs/saga-pattern.md","lastUpdated":1789023840000}'),c={name:"cs/saga-pattern.md"};function h(T,a,g,m,S,C){const s=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="saga" tabindex="-1">Saga <a class="header-anchor" href="#saga" aria-label="Permalink to &quot;Saga&quot;">​</a></h1><div class="epigraph"><p>长事务拆成一串本地事务，每步有补偿。不阻塞资源到结束，也不给全局原子：中间状态可见，补偿可能失败。</p><footer>—— 据 Garcia-Molina and Salem, Sagas, SIGMOD 1987 整理</footer></div><p>上一课<a href="/cs/idempotency-keys">幂等键</a>盖住单步骤重试。缺口是<strong>跨服务的一长串写</strong>：2PC 会把锁或连接占太久，且协调者脆。<a href="/cs/consensus-vs-2pc">共识与 2PC</a>已说明阻塞。Saga 用补偿换非阻塞，规格弱于原子提交。后课日志是实现编排的一种总线，不是 Saga 理论本身。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Garcia-Molina–Salem：saga = \\(T_1 C_1 T_2 C_2 \\ldots T_n\\)，每个 \\(T_i\\) 是本地事务，\\(C_i\\) 补偿 \\(T_i\\)。正向全成或补偿已执行前缀。隔离：saga 之间可以看见彼此的中间 \\(T_i\\)——这是相对 ACID 长事务的故意放松。</p><p>缺口：补偿不是回滚日志自动生成。订票补偿是退票，可能退不了，要人工。补偿也要幂等。编排（中心状态机）与协同（各步发事件）是实现拓扑。</p><p><span class="marginnote">1987 论文在单库长事务语境；微服务把它搬到跨进程。规格没变：可见中间态 + 补偿。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每步：本地事务 + 幂等键 + 写「saga 日志」（自身 RSM 或 DB 行）标记进度。失败：对已完成前缀逆序 \\(C_i\\)。\\(C_i\\) 失败：重试或进死信，saga 停在部分补偿——这是规格允许的坑，必须可观测。</p>',9)),(e(),n(_,null,{default:r(()=>[d(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20T1%5B%22T1%22%5D%20--%3E%20T2%5B%22T2%22%5D%0A%20%20T2%20--%3E%20T3%5B%22T3%22%5D%0A%20%20T2%20-.-%3E%20C2%5B%22C2%22%5D%0A%20%20T1%20-.-%3E%20C1%5B%22C1%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>不要用 Saga 实现转账的强不变式「永不丢钱」而不另加账本对账：中间与补偿窗口里钱在路上。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>与 2PC：2PC 准备态对外不可见（理想）；Saga 的 \\(T_i\\) 已提交，对外可见。与 RSM：可用状态机编排 saga，每转换一条日志，崩溃可恢复——恢复的是编排状态，不是把 \\(T_i\\) 变未提交。</p><p>本课不把 BPMN 引擎当定理。也不写限价簿成交链。</p><p>并发：两个 saga 改同一账户，补偿与正向交错，需要业务层锁或版本，否则补偿打到别人的后续写上。这是 1987 已点的隔离弱点。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不列补偿模式目录（retry、cancel、undo）。不引入 TCC 的 Try-Confirm 作为新理论，只点名它更接近 2PC 的资源预留。后课默认：跨服务长流程用 Saga 则接受中间可见与补偿失败路径；要原子用短 2PC 或单 RSM。Kafka 下一课提供事件序，不自动给补偿。</p><p>放松隔离是为了不阻塞。买回来的是运维与对账义务。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Saga：本地事务序列 + 补偿；中间态可见。</li><li>补偿必须幂等且可观测失败。</li><li>不替代 2PC 的原子；不替代幂等键的单步去重。</li><li>出处：Garcia-Molina and Salem, SIGMOD 1987。</li></ul>',10))])}const P=i(c,[["render",h]]);export{f as __pageData,P as default};
